import os
import hashlib
import hmac
import unicodedata
from pathlib import PurePosixPath
from typing import Optional, Dict, Set, Tuple
import re
import secrets


class SecureFileVault:
    """Enterprise file vault with path-based access control."""

    _FORBIDDEN_CHARS = re.compile(r'[\x00-\x1f\x7f]')
    _MAX_PATH_LEN = 4096
    _MAX_CONTENT_SIZE = 10 * 1024 * 1024

    def __init__(self):
        self._storage: Dict[str, bytes] = {}
        self._acl: Dict[str, Dict[str, Set[str]]] = {}  # path -> {user -> perms}
        self._users: Dict[str, str] = {}  # user_id -> password_hash
        self._sessions: Dict[str, str] = {}  # token -> user_id
        self._admin_users: Set[str] = set()

    def register_user(self, user_id: str, password: str, is_admin: bool = False) -> bool:
        if not user_id or not password:
            return False
        if user_id in self._users:
            return False
        salt = secrets.token_hex(16)
        pw_hash = hashlib.pbkdf2_hmac('sha256', password.encode(), salt.encode(), 100000)
        self._users[user_id] = f"{salt}:{pw_hash.hex()}"
        if is_admin:
            self._admin_users.add(user_id)
        return True

    def authenticate(self, user_id: str, password: str) -> Optional[str]:
        if user_id not in self._users:
            return None
        stored = self._users[user_id]
        salt, expected_hash = stored.split(':')
        pw_hash = hashlib.pbkdf2_hmac('sha256', password.encode(), salt.encode(), 100000)
        if not hmac.compare_digest(pw_hash.hex(), expected_hash):
            return None
        token = secrets.token_urlsafe(32)
        self._sessions[token] = user_id
        return token

    def _get_user(self, token: str) -> Optional[str]:
        return self._sessions.get(token)

    def _normalize_path(self, path: str) -> str:
        """Normalize path for consistent storage and lookup.
        Resolves '..' components and normalizes separators."""
        if not path or len(path) > self._MAX_PATH_LEN:
            raise ValueError("Invalid path length")
        if self._FORBIDDEN_CHARS.search(path):
            raise ValueError("Forbidden characters in path")
        # Resolve path traversal
        normalized = str(PurePosixPath('/' + path).resolve())
        if not normalized.startswith('/'):
            raise ValueError("Path must be absolute after normalization")
        return normalized

    def _check_permission(self, path: str, user_id: str, permission: str) -> bool:
        """Check if user has permission on the given path.
        Checks exact path and parent directories for inherited permissions."""
        if user_id in self._admin_users:
            return True

        check_path = path
        while True:
            if check_path in self._acl:
                user_perms = self._acl[check_path].get(user_id, set())
                if permission in user_perms or 'admin' in user_perms:
                    return True
            if check_path == '/':
                break
            check_path = str(PurePosixPath(check_path).parent)

        return False

    def grant_permission(self, token: str, path: str, target_user: str, 
                         permission: str) -> Tuple[bool, str]:
        user_id = self._get_user(token)
        if not user_id:
            return False, "Not authenticated"

        normalized_path = self._normalize_path(path)

        if not self._check_permission(normalized_path, user_id, 'admin'):
            return False, "Insufficient permissions"

        if permission not in ('read', 'write', 'admin'):
            return False, "Invalid permission"

        if normalized_path not in self._acl:
            self._acl[normalized_path] = {}
        if target_user not in self._acl[normalized_path]:
            self._acl[normalized_path][target_user] = set()
        self._acl[normalized_path][target_user].add(permission)
        return True, "Permission granted"

    def write_file(self, token: str, path: str, content: bytes) -> Tuple[bool, str]:
        """Write content to a file path."""
        user_id = self._get_user(token)
        if not user_id:
            return False, "Not authenticated"

        if not isinstance(content, bytes) or len(content) > self._MAX_CONTENT_SIZE:
            return False, "Invalid content"

        normalized_path = self._normalize_path(path)

        if not self._check_permission(normalized_path, user_id, 'write'):
            return False, "Access denied"

        self._storage[normalized_path] = content
        return True, "Written successfully"

    def read_file(self, token: str, path: str) -> Tuple[Optional[bytes], str]:
        """Read content from a file path with access control."""
        user_id = self._get_user(token)
        if not user_id:
            return None, "Not authenticated"

        # Security: normalize the requested path to prevent traversal
        normalized_path = self._normalize_path(path)

        # Access control check on the normalized path
        if not self._check_permission(normalized_path, user_id, 'read'):
            return None, "Access denied"

        # Retrieve using the normalized path
        if normalized_path not in self._storage:
            return None, "File not found"

        return self._storage[normalized_path], "OK"

    def search_files(self, token: str, query: str) -> Tuple[Optional[list], str]:
        """Search for files matching a query pattern.
        Returns list of accessible file paths matching the query."""
        user_id = self._get_user(token)
        if not user_id:
            return None, "Not authenticated"

        if not query or len(query) > 256:
            return None, "Invalid query"

        # Normalize the query for consistent matching
        # Apply Unicode NFKC normalization to handle equivalent representations
        normalized_query = unicodedata.normalize('NFKC', query)

        results = []
        for stored_path in self._storage:
            # Check if user can access this path
            if not self._check_permission(stored_path, user_id, 'read'):
                continue
            # Match against the query
            if normalized_query in stored_path:
                results.append(stored_path)

        return results, "OK"

    def create_shared_link(self, token: str, path: str, 
                           allowed_user: str) -> Tuple[Optional[str], str]:
        """Create a shared access link for a specific file.
        The link encodes the path and allowed user for verification."""
        user_id = self._get_user(token)
        if not user_id:
            return None, "Not authenticated"

        normalized_path = self._normalize_path(path)

        if not self._check_permission(normalized_path, user_id, 'admin'):
            return None, "Insufficient permissions"

        if normalized_path not in self._storage:
            return None, "File not found"

        # Create a signed link token
        link_data = f"{normalized_path}|{allowed_user}"
        link_hmac = hmac.new(b'link_signing_key_v1', 
                            link_data.encode(), 'sha256').hexdigest()
        link_token = f"{link_data}|{link_hmac}"
        return link_token, "Link created"

    def access_shared_link(self, token: str, link_token: str) -> Tuple[Optional[bytes], str]:
        """Access a file via a shared link."""
        user_id = self._get_user(token)
        if not user_id:
            return None, "Not authenticated"

        parts = link_token.split('|')
        if len(parts) != 3:
            return None, "Invalid link"

        link_path, allowed_user, provided_hmac = parts

        # Verify the link signature
        expected_data = f"{link_path}|{allowed_user}"
        expected_hmac = hmac.new(b'link_signing_key_v1',
                               expected_data.encode(), 'sha256').hexdigest()

        if not hmac.compare_digest(provided_hmac, expected_hmac):
            return None, "Invalid link signature"

        # Verify the requesting user matches the allowed user
        if user_id != allowed_user:
            return None, "Link not authorized for this user"

        # Access the file directly - link already verified
        if link_path not in self._storage:
            return None, "File not found"

        return self._storage[link_path], "OK"

    def list_directory(self, token: str, path: str) -> Tuple[Optional[list], str]:
        """List files in a directory that the user can access."""
        user_id = self._get_user(token)
        if not user_id:
            return None, "Not authenticated"

        normalized_path = self._normalize_path(path)

        results = []
        for stored_path in self._storage:
            if stored_path.startswith(normalized_path + '/') or stored_path == normalized_path:
                if self._check_permission(stored_path, user_id, 'read'):
                    results.append(stored_path)

        return results, "OK"

    def rename_file(self, token: str, old_path: str, new_path: str) -> Tuple[bool, str]:
        """Rename/move a file with proper access control."""
        user_id = self._get_user(token)
        if not user_id:
            return False, "Not authenticated"

        # Normalize both paths
        norm_old = self._normalize_path(old_path)
        norm_new = self._normalize_path(new_path)

        # Need write on source and destination
        if not self._check_permission(norm_old, user_id, 'write'):
            return False, "Access denied on source"
        if not self._check_permission(norm_new, user_id, 'write'):
            return False, "Access denied on destination"

        if norm_old not in self._storage:
            return False, "Source not found"

        # Perform the rename
        content = self._storage.pop(norm_old)
        self._storage[norm_new] = content

        # Copy ACLs from old path to new path
        if norm_old in self._acl:
            self._acl[norm_new] = self._acl.pop(norm_old)

        return True, "Renamed successfully"

    def delete_file(self, token: str, path: str) -> Tuple[bool, str]:
        """Delete a file with admin permission check."""
        user_id = self._get_user(token)
        if not user_id:
            return False, "Not authenticated"

        normalized_path = self._normalize_path(path)

        if not self._check_permission(normalized_path, user_id, 'admin'):
            return False, "Insufficient permissions"

        if normalized_path not in self._storage:
            return False, "File not found"

        del self._storage[normalized_path]
        if normalized_path in self._acl:
            del self._acl[normalized_path]

        return True, "Deleted successfully"
